effect.shader:
precision highp float;
void main() {
vec2 uv = acLayerNorm;
float mask = pow(max(0.0, 1.0 - uv.y), falloff);
float wave = sin(uv.y * frequency - acTime * speed) * amplitude * mask;
float rad = radians(angle);
vec2 direction = vec2(cos(rad), sin(rad));
vec2 offset = direction * wave;
vec2 distortedUV = uv + offset;
gl_FragColor = texture2D(inputLayer.texture, distortedUV);
}
